Fixes: 1cd3b407977c ("octeon_ep_vf: add Tx/Rx processing and interrupt support")
Cc: stable@vger.kernel.org
Signed-off-by: David Carlier <devnexen@gmail.com>
Link: https://patch.msgid.link/20260409184009.930359-3-devnexen@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function `napi_build_skb()` can return NULL on memory allocation failure, but the code in `__octep_vf_oq_process_rx()` directly used the returned pointer without a NULL check, leading to a NULL pointer dereference in both the single-buffer and multi-fragment paths.

Here is the patch:
  */
 static int __octep_vf_oq_process_rx(struct octep_vf_device *oct,
 				    struct octep_vf_oq *oq, u16 pkts_to_process)
 {
 	struct octep_vf_oq_resp_hw_ext *resp_hw_ext = NULL;
 	netdev_features_t feat = oq->netdev->features;
 	struct octep_vf_rx_buffer *buff_info;
 	struct octep_vf_oq_resp_hw *resp_hw;
 	u32 pkt, rx_bytes, desc_used;
 	u16 data_offset, rx_ol_flags;
 	struct sk_buff *skb;
 	u32 read_idx;

 	read_idx = READ_ONCE(oq->host_read_idx);
 	rx_bytes = 0;
 	desc_used = 0;
 	for (pkt = 0; pkt < pkts_to_process; pkt++) {
 		buff_info = (struct octep_vf_rx_buffer *)&oq->buff_info[read_idx];
 		dma_unmap_page(oq->dev, oq->desc_ring[read_idx].buffer_ptr,
 			       PAGE_SIZE, DMA_FROM_DEVICE);
 		resp_hw = page_address(buff_info->page);
 		buff_info->page = NULL;

 		/* Swap the length field that is in Big-Endian to CPU */
 		buff_info->len = be64_to_cpu(resp_hw->length);
 		if (oct->fw_info.rx_ol_flags) {
 			/* Extended response header is immediately after
 			 * response header (resp_hw)
 			 */
 			resp_hw_ext = (struct octep_vf_oq_resp_hw_ext *)
 				      (resp_hw + 1);
 			buff_info->len -= OCTEP_VF_OQ_RESP_HW_EXT_SIZE;
 			/* Packet Data is immediately after
 			 * extended response header.
 			 */
 			data_offset = OCTEP_VF_OQ_RESP_HW_SIZE +
 				      OCTEP_VF_OQ_RESP_HW_EXT_SIZE;
 			rx_ol_flags = resp_hw_ext->rx_ol_flags;
 		} else {
 			/* Data is immediately after
 			 * Hardware Rx response header.
 			 */
 			data_offset = OCTEP_VF_OQ_RESP_HW_SIZE;
 			rx_ol_flags = 0;
 		}
-		rx_bytes += buff_info->len;
-
 		if (buff_info->len <= oq->max_single_buffer_size) {
 			skb = napi_build_skb((void *)resp_hw, PAGE_SIZE);
+			if (!skb) {
+				oq->stats->alloc_failures++;
+				desc_used++;
+				read_idx = octep_vf_oq_next_idx(oq, read_idx);
+				continue;
+			}
+			rx_bytes += buff_info->len;
 			skb_reserve(skb, data_offset);
 			skb_put(skb, buff_info->len);
 			desc_used++;
 			read_idx = octep_vf_oq_next_idx(oq, read_idx);
 		} else {
 			struct skb_shared_info *shinfo;
 			u16 data_len;

 			skb = napi_build_skb((void *)resp_hw, PAGE_SIZE);
+			if (!skb) {
+				oq->stats->alloc_failures++;
+				desc_used++;
+				read_idx = octep_vf_oq_next_idx(oq, read_idx);
+				data_len = buff_info->len - oq->max_single_buffer_size;
+				while (data_len) {
+					dma_unmap_page(oq->dev, oq->desc_ring[read_idx].buffer_ptr,
+						       PAGE_SIZE, DMA_FROM_DEVICE);
+					buff_info = (struct octep_vf_rx_buffer *)
+						    &oq->buff_info[read_idx];
+					buff_info->page = NULL;
+					if (data_len < oq->buffer_size)
+						data_len = 0;
+					else
+						data_len -= oq->buffer_size;
+					desc_used++;
+					read_idx = octep_vf_oq_next_idx(oq, read_idx);
+				}
+				continue;
+			}
+			rx_bytes += buff_info->len;
 			skb_reserve(skb, data_offset);
 			/* Head fragment includes response header(s);
 			 * subsequent fragments contains only data.
 			 */
 			skb_put(skb, oq->max_single_buffer_size);
 			desc_used++;
 			read_idx = octep_vf_oq_next_idx(oq, read_idx);

 			shinfo = skb_shinfo(skb);
 			data_len = buff_info->len - oq->max_single_buffer_size;
 			while (data_len) {
 				dma_unmap_page(oq->dev, oq->desc_ring[read_idx].buffer_ptr,
 					       PAGE_SIZE, DMA_FROM_DEVICE);
 				buff_info = (struct octep_vf_rx_buffer *)
 					    &oq->buff_info[read_idx];
 				if (data_len < oq->buffer_size) {
 					buff_info->len = data_len;
 					data_len = 0;
 				} else {
 					buff_info->len = oq->buffer_size;
 					data_len -= oq->buffer_size;
 				}

 				skb_add_rx_frag(skb, shinfo->nr_frags,
 						buff_info->page, 0,
 						buff_info->len,
 						buff_info->len);
 				buff_info->page = NULL;
 				desc_used++;
 				read_idx = octep_vf_oq_next_idx(oq, read_idx);
 			}
 		}

 		skb->dev = oq->netdev;
 		skb->protocol = eth_type_trans(skb, skb->dev);
 		if (feat & NETIF_F_RXCSUM &&
 		    OCTEP_VF_RX_CSUM_VERIFIED(rx_ol_flags))
 			skb->ip_summed = CHECKSUM_UNNECESSARY;
 		else
 			skb->ip_summed = CHECKSUM_NONE;
 		napi_gro_receive(oq->napi, skb);
 	}

 	WRITE_ONCE(oq->host_read_idx, read_idx);
 	oq->refill_count += desc_used;
 	oq->stats->packets += pkt;
 	oq->stats->bytes += rx_bytes;

 	return pkt;
 }



